func (q *Queries) ResetMailMigrationFailures(ctx context.Context, id uuid.UUID) error {
	_, err := q.db.Exec(ctx, resetMailMigrationFailures, id)
	return err
}

const resetMailMigrationFolder = `-- name: ResetMailMigrationFolder :exec
UPDATE mail_migration_folders SET
    uid_validity = $1, last_uid = 0, updated_at = now()
WHERE id = $2
`

type ResetMailMigrationFolderParams struct {
	UidValidity int64     `json:"uid_validity"`
	ID          uuid.UUID `json:"id"`
}

// The source changed UIDVALIDITY, so every UID we recorded now names a different message. The only
// safe reading of that is that we know nothing about this folder, so the walk starts over. Duplicate
// imports are caught on arrival (JMAP reports alreadyExists) and counted as skipped.
func (q *Queries) ResetMailMigrationFolder(ctx context.Context, arg ResetMailMigrationFolderParams) error {
	_, err := q.db.Exec(ctx, resetMailMigrationFolder, arg.UidValidity, arg.ID)
	return err
}

const setMailMigrationTotal = `-- name: SetMailMigrationTotal :exec
UPDATE mail_migrations SET total_messages = $2 WHERE id = $1
`

type SetMailMigrationTotalParams struct {
	ID            uuid.UUID `json:"id"`
	TotalMessages int64     `json:"total_messages"`
}

func (q *Queries) SetMailMigrationTotal(ctx context.Context, arg SetMailMigrationTotalParams) error {
	_, err := q.db.Exec(ctx, setMailMigrationTotal, arg.ID, arg.TotalMessages)
	return err
}

const startMailMigrationFolder = `-- name: StartMailMigrationFolder :exec
UPDATE mail_migration_folders SET status = 'running', updated_at = now() WHERE id = $1
`

func (q *Queries) StartMailMigrationFolder(ctx context.Context, id uuid.UUID) error {
	_, err := q.db.Exec(ctx, startMailMigrationFolder, id)
	return err
}

const upsertMailMigrationFolder = `-- name: UpsertMailMigrationFolder :one

INSERT INTO mail_migration_folders (
    migration_id, remote_name, local_name, local_role, skip_reason, uid_validity, total_messages, status
) VALUES ($1, $2, $3, $4, $5, $6, $7,
          CASE WHEN $5::text <> '' THEN 'skipped' ELSE 'pending' END)
ON CONFLICT (migration_id, remote_name) DO UPDATE SET
    total_messages = EXCLUDED.total_messages,
    updated_at = now()
RETURNING id, migration_id, remote_name, local_name, local_role, skip_reason, uid_validity, last_uid, total_messages, copied_messages, skipped_messages, failed_messages, status, last_error, created_at, updated_at
`

type UpsertMailMigrationFolderParams struct {
	MigrationID   uuid.UUID `json:"migration_id"`
	RemoteName    string    `json:"remote_name"`
	LocalName     string    `json:"local_name"`
	LocalRole     string    `json:"local_role"`
	SkipReason    string    `json:"skip_reason"`
	UidValidity   int64     `json:"uid_validity"`
	TotalMessages int64     `json:"total_messages"`
}

// ---------- Folders ----------
// Idempotent by (migration, remote_name), because a resumed job re-lists the source and must find
// its own progress rather than start a second copy of the same folder. The counters and last_uid are
// deliberately NOT touched on conflict: they are the progress.
func (q *Queries) UpsertMailMigrationFolder(ctx context.Context, arg UpsertMailMigrationFolderParams) (MailMigrationFolder, error) {
	row := q.db.QueryRow(ctx, upsertMailMigrationFolder,
		arg.MigrationID,
		arg.RemoteName,
		arg.LocalName,
		arg.LocalRole,
		arg.SkipReason,
		arg.UidValidity,
		arg.TotalMessages,
	)
	var i MailMigrationFolder
	err := row.Scan(
		&i.ID,
		&i.MigrationID,
		&i.RemoteName,
		&i.LocalName,
		&i.LocalRole,
		&i.SkipReason,
		&i.UidValidity,
		&i.LastUid,
		&i.TotalMessages,
		&i.CopiedMessages,
		&i.SkippedMessages,
		&i.FailedMessages,
		&i.Status,
		&i.LastError,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
